import json, os
from anthropic import Anthropic

client = Anthropic(api_key=os.environ["ANTHROPIC_API_KEY"])

SCHEMA = {
    "name": "classification",
    "input_schema": {
        "type": "object",
        "properties": {
            "category": {"type": "string"},
            "urgency": {"type": "string", "enum": ["high", "medium", "low"]},
            "data": {"type": "object"},
            "confidence": {"type": "number"},
            "reason": {"type": "string"},
        },
        "required": ["category", "urgency", "confidence", "reason"],
    },
}

def classify(text: str, categories: list[str]) -> dict:
    response = client.messages.create(
        model="claude-haiku-4-5-20251001",
        max_tokens=700,
        tools=[SCHEMA],
        tool_choice={"type": "tool", "name": "classification"},
        messages=[{
            "role": "user",
            "content": (
                "Classify this case into one of these categories: "
                + ", ".join(categories)
                + ". If none fits, use 'other' and lower the confidence.\n\n"
                + text
            ),
        }],
    )
    for block in response.content:
        if block.type == "tool_use":
            return block.input
    raise ValueError("the model did not return the tool")

